  `FlightDate` date NOT NULL,
  `Gate` varchar(5) DEFAULT NULL,
  `Terminal` varchar(5) DEFAULT NULL,
  `Status` varchar(10) NOT NULL DEFAULT 'Scheduled',
  `ScheduledDepartureTime` datetime NOT NULL,
  `ActualDepartureTime` datetime DEFAULT NULL,
  `ScheduledArrivalTime` datetime NOT NULL,
  `ActualArrivalTime` datetime DEFAULT NULL,
  `DepartureAirportCode` char(3) NOT NULL,
  `ArrivalAirportCode` char(3) NOT NULL,
  PRIMARY KEY (`AirlineCode`,`FlightNumber`,`FlightDate`),
  KEY `idx_flight_departure` (`DepartureAirportCode`,`FlightDate`),
  KEY `idx_flight_arrival` (`ArrivalAirportCode`,`FlightDate`),
  KEY `idx_flight_date` (`FlightDate`),
  CONSTRAINT `fk_flight_airline` FOREIGN KEY (`AirlineCode`) REFERENCES `Airline` (`AirlineCode`) ON UPDATE CASCADE,
  CONSTRAINT `fk_flight_arrival` FOREIGN KEY (`ArrivalAirportCode`) REFERENCES `Airport` (`AirportCode`),
  CONSTRAINT `fk_flight_departure` FOREIGN KEY (`DepartureAirportCode`) REFERENCES `Airport` (`AirportCode`),
