--
-- Table structure for table `FlightStatusUpdate`
--

DROP TABLE IF EXISTS `FlightStatusUpdate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `FlightStatusUpdate` (
  `AirlineCode` char(2) NOT NULL,
  `FlightNumber` smallint NOT NULL,
  `FlightDate` date NOT NULL,
  `UpdateTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Status` varchar(10) NOT NULL,
  `UpdatedByUserID` int NOT NULL,
  PRIMARY KEY (`AirlineCode`,`FlightNumber`,`FlightDate`,`UpdateTime`),
  KEY `fk_fsu_user` (`UpdatedByUserID`),
  CONSTRAINT `fk_fsu_flight` FOREIGN KEY (`AirlineCode`, `FlightNumber`, `FlightDate`) REFERENCES `Flight` (`AirlineCode`, `FlightNumber`, `FlightDate`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_fsu_user` FOREIGN KEY (`UpdatedByUserID`) REFERENCES `User` (`UserID`) ON UPDATE CASCADE,
  CONSTRAINT `chk_fsu_status` CHECK ((`Status` in (_latin1'Scheduled',_latin1'Boarding',_latin1'Delayed',_latin1'Departed',_latin1'Arrived',_latin1'Cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

