--
-- Table structure for table `Tracks`
--

DROP TABLE IF EXISTS `Tracks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Tracks` (
  `UserID` int NOT NULL,
  `AirlineCode` char(2) NOT NULL,
  `FlightNumber` smallint NOT NULL,
  `FlightDate` date NOT NULL,
  `DateTracked` date NOT NULL DEFAULT (curdate()),
  `NotificationPreference` varchar(10) NOT NULL DEFAULT 'Email',
  PRIMARY KEY (`UserID`,`AirlineCode`,`FlightNumber`,`FlightDate`),
  KEY `idx_tracks_flight` (`AirlineCode`,`FlightNumber`,`FlightDate`),
  CONSTRAINT `fk_tracks_flight` FOREIGN KEY (`AirlineCode`, `FlightNumber`, `FlightDate`) REFERENCES `Flight` (`AirlineCode`, `FlightNumber`, `FlightDate`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_tracks_user` FOREIGN KEY (`UserID`) REFERENCES `User` (`UserID`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_tracks_pref` CHECK ((`NotificationPreference` in (_utf8mb4'Email',_utf8mb4'SMS',_utf8mb4'Push',_utf8mb4'None')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

